steps.script:
var main = tree.current_scene
for i in range(main.army_options.size()):
	if str(main.army_options[i].id) == "WPO5_E2E_Orks":
		return i
return -1

var wb := ""
var ko := ""
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) != 1:
		continue
	if str(u.meta.get("name", "")) == "Warboss":
		wb = str(uid)
	elif str(u.meta.get("name", "")) == "Kommandos":
		ko = str(uid)
GameState.state.meta["_o5_wb"] = wb
GameState.state.meta["_o5_ko"] = ko
return wb != "" and ko != ""

var e = load("res://scripts/codex/orks/OrkEnhancements11e.gd")
var wb = GameState.get_unit(str(GameState.state.meta["_o5_wb"]))
var ko = GameState.get_unit(str(GameState.state.meta["_o5_ko"]))
print("[wp-o5 builder] Warboss enh=", wb.meta.get("enhancements"), " Kommandos enh=", ko.meta.get("enhancements"))
return [e.has(wb, "kill_kommanda"), e.has(ko, "throat_slittas")]

var w = ArmyListManager.validate_army_construction_11e(ArmyListManager.cloud_army_cache.get("WPO5_E2E_Orks", {})).warnings
var bad := []
for x in w:
	if str(x).contains("Codex: Orks"):
		bad.append(str(x))
return str(bad)

var oa = load("res://scripts/codex/orks/OrkAbilities11e.gd")
var ko = GameState.get_unit(str(GameState.state.meta["_o5_ko"]))
for uid in GameState.state.units:
	var t = GameState.state.units[uid]
	if int(t.get("owner", 0)) == 2 and "INFANTRY" in t.meta.get("keywords", []) and not "MONSTER" in t.meta.get("keywords", []) and not "VEHICLE" in t.meta.get("keywords", []):
		return bool(oa.attack_mods(ko, t, {"name": "Choppa", "type": "Melee"}, true, GameState.state, []).get("lethal", false))
return "no P2 infantry"

var fd = tree.current_scene.formations_dialog
if fd == null or not is_instance_valid(fd) or not fd.visible:
	return "no formations dialog"
var wb := str(GameState.state.meta["_o5_wb"])
var ko := str(GameState.state.meta["_o5_ko"])
for ob in fd.find_children("*", "OptionButton", true, false):
	if str(ob.get_meta("character_id", "")) == wb:
		for i in range(ob.item_count):
			if str(ob.get_item_metadata(i)) == ko:
				GameState.state.meta["_o5_idx"] = i
				return true
		return "Kommandos not offered to the Warboss"
return "no Warboss row"

var fd = tree.current_scene.formations_dialog
var wb := str(GameState.state.meta["_o5_wb"])
for ob in fd.find_children("*", "OptionButton", true, false):
	if str(ob.get_meta("character_id", "")) == wb:
		var i := int(GameState.state.meta["_o5_idx"])
		ob.select(i)
		ob.item_selected.emit(i)
		return ob.get_item_text(ob.selected).begins_with("Kommandos")
return false

var p = PhaseManager.get_current_phase_instance()
var la = p.player_formations.get(1, {}).get("leader_attachments", {})
return str(la.get(str(GameState.state.meta["_o5_wb"]), "")) == str(GameState.state.meta["_o5_ko"])
